import { answer, field as f, fixture as r, hints as h, option as o, quantity as q } from "../casework";
import type { CaseDraft, Casework } from "../casework";

const pilotBase: Readonly<Record<string, readonly [latency: number, cost: number]>> = { A: [1.6, 1.8], B: [2.7, 3.3], C: [1.9, 1.7] };

function pilotRecord({ candidate, close }: CaseDraft) {
  const staff = close === "Staff before closure";
  const [latency, cost] = pilotBase[String(candidate)] ?? [0, 0];
  return { staff, latency: latency + (staff ? .2 : 0), cost: cost + (staff ? .1 : 0) };
}

const reviewerMinutes: Readonly<Record<string, number>> = { "Exact string match": 0, "Calibrated review": 48, "Model self-score": 0, "Thumbs-up rate": 0 };

const incidentMinutes: Readonly<Record<"page" | "queue" | "investigate", Readonly<Record<string, number>>>> = {
  page: { "Post dashboard": 5, "Page on-call": 1, "Email the team": 4, "Ping vendor": 3 },
  queue: { "Wait for deploy": 8, "Open staffed queue": 3, "Hold in write queue": 2, "Auto-reply only": 1 },
  investigate: { "Full dashboard export": 7, "Identity + scope diff": 2, "Restart workers": 2, "Raise log levels": 2 },
};

